alter policy "Scoped attendance records" on public.schoolpro_attendance with check (private.schoolpro_can_read_student(student_id) and exists(select 1 from public.schoolpro_students s where s.id=schoolpro_attendance.student_id and s.school_id=schoolpro_attendance.school_id and (exists(select 1 from public.schoolpro_enrollment_history h where h.school_id=s.school_id and h.student_id=s.id and h.session=schoolpro_attendance.session and h.class_id=schoolpro_attendance.class_id) or (not exists(select 1 from public.schoolpro_enrollment_history h where h.student_id=s.id) and s.class_id=schoolpro_attendance.class_id))));